insert into public.survey_versions(id,title,approved,questions) values('approved-2026-11-11-v2','나를 알아가는 질문',true,'[{"id":"a01","section":"A","kind":"scale","text":"손으로 물건을 만들거나 고치는 활동이 궁금하다."},{"id":"a02","section":"A","kind":"scale","text":"식물이나 동물을 관찰하고 돌보는 활동이 궁금하다."},{"id":"a03","section":"A","kind":"scale","text":"음식이나 음료를 만드는 과정을 더 배워 보고 싶다."},{"id":"a04","section":"A","kind":"scale","text":"그림이나 사진으로 내 생각을 표현하는 활동이 궁금하다."},{"id":"a05","section":"A","kind":"scale","text":"음악을 만들거나 연주하는 활동이 궁금하다."},{"id":"a06","section":"A","kind":"scale","text":"운동이나 몸을 움직이는 활동을 더 해보고 싶다."},{"id":"a07","section":"A","kind":"scale","text":"이야기나 글을 쓰는 활동이 궁금하다."},{"id":"a08","section":"A","kind":"scale","text":"사람들의 이야기를 듣고 도움을 주는 활동이 궁금하다."},{"id":"a09","section":"A","kind":"scale","text":"물건을 소개하거나 판매하는 활동이 궁금하다."},{"id":"a10","section":"A","kind":"scale","text":"컴퓨터로 새로운 것을 만드는 활동이 궁금하다."},{"id":"a11","section":"A","kind":"scale","text":"숫자나 기록에서 규칙을 찾는 활동이 궁금하다."},{"id":"a12","section":"A","kind":"scale","text":"기계나 전자 기기가 움직이는 원리가 궁금하다."},{"id":"a13","section":"A","kind":"scale","text":"여행 장소나 행사를 계획하는 활동이 궁금하다."},{"id":"a14","section":"A","kind":"scale","text":"옷이나 공간을 꾸미는 활동이 궁금하다."},{"id":"a15","section":"A","kind":"scale","text":"실험으로 궁금한 것을 확인하는 활동이 궁금하다."},{"id":"a16","section":"A","kind":"scale","text":"외국어로 다른 사람과 소통하는 활동이 궁금하다."},{"id":"a17","section":"A","kind":"scale","text":"사람들 앞에서 설명하거나 발표하는 활동이 궁금하다."},{"id":"a18","section":"A","kind":"scale","text":"영상이나 게임이 만들어지는 과정이 궁금하다."},{"id":"a19","section":"A","kind":"scale","text":"역사나 문화를 찾아보며 사람들의 생활을 알아보는 활동이 궁금하다."},{"id":"a20","section":"A","kind":"scale","text":"생활 속 불편이나 환경 문제를 줄이는 활동이 궁금하다."},{"id":"b01","section":"B","kind":"scale","text":"문제가 생기면 원인을 하나씩 찾아보는 편이다."},{"id":"b02","section":"B","kind":"scale","text":"한 가지 문제에 여러 해결 방법을 생각해 보는 편이다."},{"id":"b03","section":"B","kind":"scale","text":"새로운 아이디어를 떠올리는 일이 재미있다."},{"id":"b04","section":"B","kind":"scale","text":"복잡한 일을 만나면 할 일을 작은 단계로 나눠 보는 편이다."},{"id":"b05","section":"B","kind":"scale","text":"궁금한 내용은 자료를 찾아 확인하는 편이다."},{"id":"b06","section":"B","kind":"scale","text":"해본 방법이 안 되면 다른 방법을 시도하는 편이다."},{"id":"b07","section":"B","kind":"scale","text":"방법을 잘 모를 때 다른 사람에게 도움을 요청하는 편이다."},{"id":"b08","section":"B","kind":"scale","text":"설명과 실제 결과가 다르면 이유가 궁금하다."},{"id":"b09","section":"B","kind":"scale","text":"물건이나 서비스의 불편한 점을 개선해 보고 싶다."},{"id":"b10","section":"B","kind":"scale","text":"해결한 과정을 다른 사람에게 설명해 보는 편이다."},{"id":"c01","section":"C","kind":"scale","text":"직접 해보면서 배우면 이해하기 편하다."},{"id":"c02","section":"C","kind":"scale","text":"글이나 설명을 먼저 읽으면 배우기 편하다."},{"id":"c03","section":"C","kind":"scale","text":"혼자 집중해서 할 일이 있을 때는 조용한 곳이 편하다."},{"id":"c04","section":"C","kind":"scale","text":"함께 할 일이 있을 때 서로 의견을 주고받으며 작업하는 것이 좋다."},{"id":"c05","section":"C","kind":"scale","text":"혼자 생각할 시간이 있으면 편하다."},{"id":"c06","section":"C","kind":"scale","text":"시작 전에 순서를 정하면 편하다."},{"id":"c07","section":"C","kind":"scale","text":"상황에 맞게 계획을 바꾸는 것이 편하다."},{"id":"c08","section":"C","kind":"scale","text":"연습하기 전보다 나아진 점을 확인하면 계속해 보고 싶다."},{"id":"c09","section":"C","kind":"scale","text":"어려울 때 질문할 사람이 있으면 배우기 편하다."},{"id":"c10","section":"C","kind":"scale","text":"같은 활동을 반복해서 익히는 것이 편하다."},{"id":"d01","section":"D","kind":"scale","text":"고등학교를 고를 때 편안하게 생활할 수 있는 분위기를 중요하게 생각한다."},{"id":"d02","section":"D","kind":"scale","text":"직업을 선택할 때 생활의 안정성이 중요하다."},{"id":"d03","section":"D","kind":"scale","text":"내가 재미를 느끼는 일을 더 배우는 것이 중요하다."},{"id":"d04","section":"D","kind":"scale","text":"다른 사람에게 도움이 되는 일을 하고 싶다."},{"id":"d05","section":"D","kind":"scale","text":"고등학교에서도 진학과 취업 가능성을 함께 알아보고 싶다."},{"id":"e01","section":"E","kind":"scale","text":"예전에 어려웠던 활동도 다른 방식으로 다시 경험해 보고 싶다."},{"id":"e02","section":"E","kind":"scale","text":"좋아하는 활동의 어떤 점이 좋은지 설명할 수 있다."},{"id":"e03","section":"E","kind":"scale","text":"잘 모르겠는 분야는 짧게 체험해 보고 판단하고 싶다."},{"id":"e04","section":"E","kind":"scale","text":"주변의 추천과 내 생각이 다를 때 내 이유를 말하고 싶다."},{"id":"e05","section":"E","kind":"scale","text":"학교나 진로를 정하기에는 아직 경험이나 정보가 부족하다고 느낀다."},{"id":"t01","section":"T","kind":"text","text":"고등학교에서 하루를 보낸다면 어떤 시간이 있으면 좋겠어? 떠오르는 수업이나 쉬는 시간의 모습을 하나만 적어도 돼."},{"id":"t02","section":"T","kind":"text","text":"배우다가 어려웠던 일이 있다면, 어떤 도움이나 다른 방법이 있었으면 좋았을까? 지금도 해보고 있는 일이나 학교 공부 이야기여도 괜찮아."},{"id":"t03","section":"T","kind":"text","text":"네가 말하는 편한 학교 분위기는 어떤 모습이야? 불편하거나 피하고 싶은 상황을 적어도 돼."},{"id":"t04","section":"T","kind":"text","text":"지금 관심 있는 학교나 학과가 있다면, 직접 해보고 싶은 수업과 아직 확인하고 싶은 점을 적어 줄래? 아직 없어도 괜찮아."},{"id":"t05","section":"T","kind":"text","text":"학교를 비교하는 데 더 알아보고 싶은 정보나 짧게 해보고 싶은 체험이 있을까? 형에게 바라는 도움이 있으면 적어도 돼. 아직 모르겠어도 괜찮아."}]'::jsonb) on conflict(id) do nothing;
insert into public.schools(id,name,details) values('gukwon','국원고등학교','{"id":"gukwon","name":"국원고등학교","type":"일반고","ownership":"공립","gender":"남녀공학","maleEligibility":"가능","address":"충청북도 충주시 탄금대로 88","homepage":"https://school.cbe.go.kr/gukwon-h/","admissionsUrl":"https://school.cbe.go.kr/daeje-m/M01030402/view/5829437","verification":"일부 확인","checkedAt":"2026-11-11","summary":"교과 선택과 학교생활을 살펴보며 탐색할 수 있어요.","curriculum":"2027학년도 교육과정 편제·선택과목 공식 자료 확인 필요","pathway":"대학 진학·취업 경로 및 최근 실적 공식 자료 확인 필요","commute":"출발 지역에서의 실제 등하교 노선·시간 공식 자료 확인 필요 (거리·시간을 추정하지 않았습니다.)","notes":"남학생 지원 표시는 성별 조건에 한정합니다. 졸업·거주·전형별 자격은 원서 작성 전 담임선생님 및 학교에 확인해야 합니다.","departments":[{"id":"gukwon-general","name":"일반 교육과정","capacity":null,"subjects":"2027학년도 선택과목 공식 자료 확인 필요","certifications":"학교별 운영 여부 공식 자료 확인 필요","pathway":"과목 선택 및 진로·진학 상담 프로그램 공식 자료 확인 필요"}],"sources":[{"url":"https://open.neis.go.kr/hub/schoolInfo?Type=json&ATPT_OFCDC_SC_CODE=M10&SCHUL_NM=%EA%B5%AD%EC%9B%90%EA%B3%A0%EB%93%B1%ED%95%99%EA%B5%90","title":"NEIS 학교기본정보 (적재 2026-04-23, 조회 2026-11-11)"},{"url":"https://school.cbe.go.kr/daeje-m/M01030402/view/5829437","title":"2027학년도 입학전형 자료"}],"applicationPeriod":"2026.12.07.~12.10. 17:00 (교육감전형 요강)","selection":"충주 평준화: 내신 300점으로 선발 후 성적군별 지망에 따라 컴퓨터 무작위 추첨 배정. 충주 4교 희망 순위 작성."}'::jsonb) on conflict(id) do update set name=excluded.name,details=excluded.details;
insert into public.departments(id,school_id,name,details) values('gukwon-general','gukwon','일반 교육과정','{"id":"gukwon-general","name":"일반 교육과정","capacity":null,"subjects":"2027학년도 선택과목 공식 자료 확인 필요","certifications":"학교별 운영 여부 공식 자료 확인 필요","pathway":"과목 선택 및 진로·진학 상담 프로그램 공식 자료 확인 필요"}'::jsonb) on conflict(id) do update set name=excluded.name,details=excluded.details;
insert into public.schools(id,name,details) values('chungju','충주고등학교','{"id":"chungju","name":"충주고등학교","type":"일반고","ownership":"공립","gender":"남","maleEligibility":"가능","address":"충청북도 충주시 예성로 37","homepage":"https://school.cbe.go.kr/chungju-h/","admissionsUrl":"https://school.cbe.go.kr/daeje-m/M01030402/view/5829437","verification":"일부 확인","checkedAt":"2026-11-11","summary":"교과 선택과 학교생활을 살펴보며 탐색할 수 있어요.","curriculum":"2027학년도 교육과정 편제·선택과목 공식 자료 확인 필요","pathway":"대학 진학·취업 경로 및 최근 실적 공식 자료 확인 필요","commute":"출발 지역에서의 실제 등하교 노선·시간 공식 자료 확인 필요 (거리·시간을 추정하지 않았습니다.)","notes":"남학생 지원 표시는 성별 조건에 한정합니다. 졸업·거주·전형별 자격은 원서 작성 전 담임선생님 및 학교에 확인해야 합니다. NEIS 학교유형은 자율고이며 화면에서는 일반고 탐색에 함께 표시합니다.","departments":[{"id":"chungju-general","name":"일반 교육과정","capacity":null,"subjects":"2027학년도 선택과목 공식 자료 확인 필요","certifications":"학교별 운영 여부 공식 자료 확인 필요","pathway":"과목 선택 및 진로·진학 상담 프로그램 공식 자료 확인 필요"}],"sources":[{"url":"https://open.neis.go.kr/hub/schoolInfo?Type=json&ATPT_OFCDC_SC_CODE=M10&SCHUL_NM=%EC%B6%A9%EC%A3%BC%EA%B3%A0%EB%93%B1%ED%95%99%EA%B5%90","title":"NEIS 학교기본정보 (적재 2026-04-23, 조회 2026-11-11)"},{"url":"https://school.cbe.go.kr/daeje-m/M01030402/view/5829437","title":"2027학년도 입학전형 자료"}],"applicationPeriod":"2026.12.07.~12.10. 17:00 (교육감전형 요강)","selection":"충주 평준화: 내신 300점으로 선발 후 성적군별 지망에 따라 컴퓨터 무작위 추첨 배정. 충주 4교 희망 순위 작성."}'::jsonb) on conflict(id) do update set name=excluded.name,details=excluded.details;
insert into public.departments(id,school_id,name,details) values('chungju-general','chungju','일반 교육과정','{"id":"chungju-general","name":"일반 교육과정","capacity":null,"subjects":"2027학년도 선택과목 공식 자료 확인 필요","certifications":"학교별 운영 여부 공식 자료 확인 필요","pathway":"과목 선택 및 진로·진학 상담 프로그램 공식 자료 확인 필요"}'::jsonb) on conflict(id) do update set name=excluded.name,details=excluded.details;
insert into public.schools(id,name,details) values('cjth','충주공업고등학교','{"id":"cjth","name":"충주공업고등학교","type":"특성화고","ownership":"공립","gender":"남녀공학","maleEligibility":"가능","address":"충청북도 충주시 형설로 120","homepage":"https://school.cbe.go.kr/cjth-h/","admissionsUrl":"https://school.cbe.go.kr/cjth-h/M010301/view/5859620","verification":"일부 확인","checkedAt":"2026-11-11","summary":"토목·건축·전기전자·기계 분야의 전공을 살펴볼 수 있어요.","curriculum":"학교 공식 학과소개 교육내용 확인(2026-11-11). 적용연도 미표기이며 2027 입학생 편제·실제 개설은 별도 확인 필요.","pathway":"학과별 공식 안내의 진로 방향을 확인했습니다. 취업·진학 보장 또는 실적 수치가 아니며 2027 프로그램은 별도 확인 필요.","commute":"출발 지역에서의 실제 등하교 노선·시간 공식 자료 확인 필요 (거리·시간을 추정하지 않았습니다.)","notes":"남학생 지원 표시는 성별 조건에 한정합니다. 졸업·거주·전형별 자격은 원서 작성 전 담임선생님 및 학교에 확인해야 합니다. 2027요강 HWP 기준 정원140명/7학급. 체육특기자 인원은 본문8명과 별지9명이 충돌하여 미확정.","departments":[{"id":"cjth-civil","name":"토목시스템과","capacity":40,"subjects":"공식 학과소개(적용연도 미표기, 2026-11-11 확인): 측량, 지적, 드론공간정보구축, 소형무인기운용조종, 토목도면해석 및 제도 등. 2027 개설 보장은 아님.","certifications":"학교 안내 예: 측량·지적·전산응용토목제도·콘크리트 기능사, 드론 관련 자격 등. 2027 교육·취득 지원은 별도 확인 필요.","pathway":"도로·철도·교량의 조사·설계 및 건설 유지관리 분야를 안내. 공무원·공기업 취업 보장이 아님."},{"id":"cjth-architecture","name":"건축디자인과","capacity":20,"subjects":"공식 학과소개(적용연도 미표기, 2026-11-11 확인): 기초제도, 건축기초실습, 건축일반, 실내디자인, 건축마감·목공·도장시공 등. 2027 개설 보장은 아님.","certifications":"학교 안내 예: 전산응용건축제도·실내건축·건축도장·건축목공 기능사 등. 2027 교육·취득 지원은 별도 확인 필요.","pathway":"건축 설계·공간 구성·시공 관련 분야를 안내. 취업·진학 실적은 별도 확인."},{"id":"cjth-electric","name":"전기전자과","capacity":40,"subjects":"공식 학과소개(적용연도 미표기, 2026-11-11 확인): 전기·전자회로, 디지털논리회로, 전기기기, 내선공사, 자동제어시스템운영 등. 2027 개설 보장은 아님.","certifications":"학교 안내 예: 전기·전자·승강기·철도전기신호·3D프린터운용 기능사 등. 2027 교육·취득 지원은 별도 확인 필요.","pathway":"전기·전자 현장, 자동제어 장비·설비 유지보수 분야를 안내. 취업 보장이 아님."},{"id":"cjth-machine","name":"자동화기계과","capacity":40,"subjects":"공식 학과소개(적용연도 미표기, 2026-11-11 확인): 기초제도, 기계기초공작, 기계수동조립, 선반·밀링가공, 측정, 기계요소설계 등. 2027 개설 보장은 아님.","certifications":"학교 안내 예: 컴퓨터응용선반·밀링·설비보전·전산응용기계제도·기계가공조립 기능사 등. 2027 교육·취득 지원은 별도 확인 필요.","pathway":"기계공업 관련 기술 분야를 안내. 구체 진학·취업 프로그램과 실적은 별도 확인."}],"sources":[{"url":"https://open.neis.go.kr/hub/schoolInfo?Type=json&ATPT_OFCDC_SC_CODE=M10&SCHUL_NM=%EC%B6%A9%EC%A3%BC%EA%B3%B5%EC%97%85%EA%B3%A0%EB%93%B1%ED%95%99%EA%B5%90","title":"NEIS 학교기본정보 (적재 2026-04-23, 조회 2026-11-11)"},{"url":"https://school.cbe.go.kr/cjth-h/M010301/view/5859620","title":"2027학년도 입학전형 자료"},{"url":"https://school.cbe.go.kr/cjth-h/M01020801/","title":"토목시스템과 공식 소개(적용연도 미표기, 2026-11-11 확인)"},{"url":"https://school.cbe.go.kr/cjth-h/M01020802/","title":"건축디자인과 공식 소개(적용연도 미표기, 2026-11-11 확인)"},{"url":"https://school.cbe.go.kr/cjth-h/M01020803/","title":"전기전자과 공식 소개(적용연도 미표기, 2026-11-11 확인)"},{"url":"https://school.cbe.go.kr/cjth-h/M01020804/","title":"자동화기계과 공식 소개(적용연도 미표기, 2026-11-11 확인)"}],"applicationPeriod":"특별전형 2026.11.20. 17:00까지 / 일반전형 2026.11.27.~12.01. 17:00","selection":"일반전형 내신 및 학과지망순 사정. 특별전형은 1개 학과 지원, 1차 내신50%·2차 면접50%, 취업 의지 조건."}'::jsonb) on conflict(id) do update set name=excluded.name,details=excluded.details;
