insert into public.schools(id,name,details) values('chungjuch','충주상업고등학교','{"id":"chungjuch","name":"충주상업고등학교","type":"특성화고","ownership":"사립","gender":"남녀공학","maleEligibility":"가능","address":"충청북도 충주시 방아길 20","homepage":"https://school.cbe.go.kr/chungjuch-h/","admissionsUrl":"https://school.cbe.go.kr/chungjuch-h/MABAGBH/view/5823607","verification":"일부 확인","checkedAt":"2026-11-11","summary":"경영·회계, IT, 관광, 조리를 학과별로 비교해 볼 수 있어요.","curriculum":"학교 공식 학과소개 교육내용 확인(2026-11-11). 적용연도 미표기이며 2027 입학생 편제·실제 개설은 별도 확인 필요.","pathway":"학과별 공식 안내의 진로 방향을 확인했습니다. 취업·진학 보장 또는 실적 수치가 아니며 2027 프로그램은 별도 확인 필요.","commute":"출발 지역에서의 실제 등하교 노선·시간 공식 자료 확인 필요 (거리·시간을 추정하지 않았습니다.)","notes":"남학생 지원 표시는 성별 조건에 한정합니다. 졸업·거주·전형별 자격은 원서 작성 전 담임선생님 및 학교에 확인해야 합니다. 2027요강 HWP 기준 정원140명/7학급. HTML 특별전형11월22일(금) 표기는 HWP11월20일(금)과 불일치하므로 HWP를 우선하고 학교 재확인 권장. 최종 정원은 조정 가능.","departments":[{"id":"chungjuch-accounting","name":"경영회계과","capacity":40,"subjects":"공식 학과소개(적용연도 미표기, 2026-11-11 확인): 경영·회계 업무 실무역량을 배우는 학과로 안내. 2027 과목명은 미확인. 2027 개설 보장은 아님.","certifications":"학교 안내 예: 컴퓨터활용능력, 전산회계, ERP정보관리, ITQ·GTQ. 현재 자격 명칭·응시조건 별도 확인. 2027 교육·취득 지원은 별도 확인 필요.","pathway":"경영·회계·금융·회계사무 분야와 관련 대학 진학을 안내. 취업·진학 실적이 아님."},{"id":"chungjuch-management","name":"경영관리과","capacity":40,"subjects":"공식 학과소개(적용연도 미표기, 2026-11-11 확인): 경영지원과 생산·품질·유통 업무 기초를 배우는 학과로 안내. 2027 과목명은 미확인. 2027 개설 보장은 아님.","certifications":"학교 안내 예: 컴퓨터활용능력, 유통관리사, FAT·TAT, ERP, ITQ·GTQ. 현재 응시조건 별도 확인. 2027 교육·취득 지원은 별도 확인 필요.","pathway":"인사·물류·유통·생산·품질 관리 등의 분야를 안내. 취업 보장이 아님."},{"id":"chungjuch-it","name":"스마트IT과","capacity":20,"subjects":"공식 학과소개(적용연도 미표기, 2026-11-11 확인): 소프트웨어 분석·설계·구현·시험·유지보수 역량 학습을 안내. 2027 과목명은 미확인. 2027 개설 보장은 아님.","certifications":"학교 안내 예: 정보처리기능사, 정보기기운용기능사, ITQ·GTQ. 현재 응시조건 별도 확인. 2027 교육·취득 지원은 별도 확인 필요.","pathway":"소프트웨어·앱·웹 개발 등의 분야를 안내. 취업 보장이 아님."},{"id":"chungjuch-tourism","name":"관광레저과","capacity":20,"subjects":"공식 학과소개(적용연도 미표기, 2026-11-11 확인): 호텔·외식 서비스, 여행·레저·컨벤션 관련 교육 방향을 안내. 2027 과목명은 미확인. 2027 개설 보장은 아님.","certifications":"학교 안내 예: 조주기능사, 서비스경영능력자격, 바리스타, 국내여행안내사 등. 국가·민간 구분과 응시조건 별도 확인. 2027 교육·취득 지원은 별도 확인 필요.","pathway":"호텔·음료·여행·컨벤션 서비스 등의 분야를 안내. 취업 보장이 아님."},{"id":"chungjuch-cooking","name":"외식조리과","capacity":20,"subjects":"공식 학과소개(적용연도 미표기, 2026-11-11 확인): 음식 조리의 기초 지식·기능과 실무를 배우는 학과로 안내. 2027 과목명은 미확인. 2027 개설 보장은 아님.","certifications":"학교 안내 예: 한식·양식·일식·중식 조리기능사. 응시 및 교육 지원 조건 별도 확인. 2027 교육·취득 지원은 별도 확인 필요.","pathway":"호텔·외식업체·급식·제과제빵 등의 진로 방향을 안내. 취업 보장이 아님."}],"sources":[{"url":"https://open.neis.go.kr/hub/schoolInfo?Type=json&ATPT_OFCDC_SC_CODE=M10&SCHUL_NM=%EC%B6%A9%EC%A3%BC%EC%83%81%EC%97%85%EA%B3%A0%EB%93%B1%ED%95%99%EA%B5%90","title":"NEIS 학교기본정보 (적재 2026-04-23, 조회 2026-11-11)"},{"url":"https://school.cbe.go.kr/chungjuch-h/MABAGBH/view/5823607","title":"2027학년도 입학전형 자료"},{"url":"https://school.cbe.go.kr/chungjuch-h/M01020501/","title":"경영회계과 공식 소개(적용연도 미표기, 2026-11-11 확인)"},{"url":"https://school.cbe.go.kr/chungjuch-h/M01020506/","title":"경영관리과 공식 소개(적용연도 미표기, 2026-11-11 확인)"},{"url":"https://school.cbe.go.kr/chungjuch-h/M01020503/","title":"스마트IT과 공식 소개(적용연도 미표기, 2026-11-11 확인)"},{"url":"https://school.cbe.go.kr/chungjuch-h/M01020504/","title":"관광레저과 공식 소개(적용연도 미표기, 2026-11-11 확인)"},{"url":"https://school.cbe.go.kr/chungjuch-h/M01020505/","title":"외식조리과 공식 소개(적용연도 미표기, 2026-11-11 확인)"}],"applicationPeriod":"특별전형 2026.11.20. 17:00까지 / 일반전형 2026.11.27.~12.01. 17:00","selection":"일반전형 내신, 1지망 학과별 성적순 우선 선발 후 미달 학과에 2~5지망 적용. 특별전형은 자격증·내신·면접 평가."}'::jsonb) on conflict(id) do update set name=excluded.name,details=excluded.details;
