insert into public.schools(id,name,details) values('had','한림디자인고등학교','{"id":"had","name":"한림디자인고등학교","type":"특성화고","ownership":"사립","gender":"여","maleEligibility":"불가","address":"충청북도 충주시 야현1길 21","homepage":"https://school.cbe.go.kr/had-h/","admissionsUrl":"https://school.cbe.go.kr/had-h/M0112","verification":"일부 확인","checkedAt":"2026-11-11","summary":"여학생 모집 학교로, 남학생 지원 대상에서 제외해요.","curriculum":"학교 공식 학과소개 교육내용 확인(2026-11-11). 적용연도 미표기이며 2027 입학생 편제·실제 개설은 별도 확인 필요.","pathway":"학과별 공식 안내의 진로 방향을 확인했습니다. 취업·진학 보장 또는 실적 수치가 아니며 2027 프로그램은 별도 확인 필요.","commute":"출발 지역에서의 실제 등하교 노선·시간 공식 자료 확인 필요 (거리·시간을 추정하지 않았습니다.)","notes":"남학생 지원 표시는 성별 조건에 한정합니다. 졸업·거주·전형별 자격은 원서 작성 전 담임선생님 및 학교에 확인해야 합니다. NEIS 여학교 분류 확인. 2027 공식 게시 HWP 및 이미지1페이지: 여자160명/8학급. 파일제목은 승인 자료이나 문서제목에 (안)이 남아 있어 최신 정정 여부 확인 필요.","departments":[{"id":"had-accounting","name":"경영회계과","capacity":20,"subjects":"공식 학과소개(적용연도 미표기, 2026-11-11 확인): 상업경제·회계원리·세무일반, 회계실무·세무실무·사무행정·유통관리 등. 2027 개설 보장은 아님.","certifications":"학교 안내 예: 전산회계·전산회계운용사·정보관리사·컴퓨터활용능력 등. 2027 교육·취득 지원은 별도 확인 필요.","pathway":"경영·경제·무역 관련 대학 및 경영지원·세무회계 분야를 안내. 여학생 모집이며 실적과 구분."},{"id":"had-visual","name":"시각디자인과","capacity":40,"subjects":"공식 학과소개(적용연도 미표기, 2026-11-11 확인): 디자인일반·컴퓨터그래픽·조형·시각디자인·색채디자인·광고콘텐츠제작 등. 2027 개설 보장은 아님.","certifications":"학교 안내 예: 시각디자인산업기사·컴퓨터그래픽기능사·전자출판기능사·GTQ 등. 응시조건 별도 확인. 2027 교육·취득 지원은 별도 확인 필요.","pathway":"광고·그래픽·웹·일러스트 등 디자인 분야를 안내. 여학생 모집이며 취업 보장이 아님."},{"id":"had-sculpture","name":"조형디자인과","capacity":40,"subjects":"공식 학과소개(적용연도 미표기, 2026-11-11 확인): 조형·기초제도·디자인제도·3D제작디자인·제품디자인·실내디자인·입체조형 등. 2027 개설 보장은 아님.","certifications":"학교 안내 예: 컬러리스트산업기사·컴퓨터그래픽기능사·3D프린팅기능사·GTQ 등. 응시조건 별도 확인. 2027 교육·취득 지원은 별도 확인 필요.","pathway":"제품·3D모델링·인테리어·공간 디자인 등의 분야를 안내. 여학생 모집이며 실적과 구분."},{"id":"had-fashion","name":"패션디자인과","capacity":20,"subjects":"공식 학과소개(적용연도 미표기, 2026-11-11 확인): 패션디자인 기초·실제, 패턴메이킹, 의류재료관리, 서양의복구성과생산 등. 2027 개설 보장은 아님.","certifications":"학교 안내 예: 양장기능사·샵마스터·GTQ포토샵 등. 국가·민간 구분 및 응시조건 별도 확인. 2027 교육·취득 지원은 별도 확인 필요.","pathway":"의상·패션 관련 진학과 제조·유통·스타일링 분야를 안내. 여학생 모집이며 실적과 구분."},{"id":"had-beauty","name":"뷰티디자인과","capacity":40,"subjects":"공식 학과소개(적용연도 미표기, 2026-11-11 확인): 미용기초·안전보건·헤어미용·네일미용·피부미용·메이크업 및 현장 실무. 2027 개설 보장은 아님.","certifications":"학교 안내 예: 미용사(일반·피부·메이크업·네일). 과정평가형과 일반검정형 경로 안내; 현재 운영조건 별도 확인. 2027 교육·취득 지원은 별도 확인 필요.","pathway":"미용·메이크업·피부·네일 등의 진학·직업 분야를 안내. 여학생 모집이며 실적과 구분."}],"sources":[{"url":"https://open.neis.go.kr/hub/schoolInfo?Type=json&ATPT_OFCDC_SC_CODE=M10&SCHUL_NM=%ED%95%9C%EB%A6%BC%EB%94%94%EC%9E%90%EC%9D%B8%EA%B3%A0%EB%93%B1%ED%95%99%EA%B5%90","title":"NEIS 학교기본정보 (적재 2026-04-23, 조회 2026-11-11)"},{"url":"https://school.cbe.go.kr/had-h/M0112","title":"2027학년도 입학전형 자료"},{"url":"https://school.cbe.go.kr/had-h/M01020503/","title":"경영회계과 공식 소개(적용연도 미표기, 2026-11-11 확인)"},{"url":"https://school.cbe.go.kr/had-h/MABACAFBA/","title":"시각디자인과 공식 소개(적용연도 미표기, 2026-11-11 확인)"},{"url":"https://school.cbe.go.kr/had-h/MABACAFBB/","title":"조형디자인과 공식 소개(적용연도 미표기, 2026-11-11 확인)"},{"url":"https://school.cbe.go.kr/had-h/M01020506/","title":"패션디자인과 공식 소개(적용연도 미표기, 2026-11-11 확인)"},{"url":"https://school.cbe.go.kr/had-h/M01020507/","title":"뷰티디자인과 공식 소개(적용연도 미표기, 2026-11-11 확인)"}],"applicationPeriod":"특별전형 2026.11.20. 17:00까지 / 일반전형 2026.11.27.~12.01. 17:00","selection":"일반전형: 내신 성적으로 선발. 특별전형: 학교별 취업희망자 전형 기준 확인."}'::jsonb) on conflict(id) do update set name=excluded.name,details=excluded.details;
